2	import { createContext, useContext, useEffect, useMemo } from 'react';
3	import { useLocalStorage } from '@/hooks/use-local-storage';
4	
5	type Theme = 'light' | 'dark' | 'system';
6	const ThemeContext = createContext<{ theme: Theme; setTheme: (t: Theme) => void }>({
7	  theme: 'system',
8	  setTheme: () => {},
9	});
