11	export function ThemeProvider({ children }: { children: React.ReactNode }) {
12	  const [theme, setTheme] = useLocalStorage<Theme>('theme', 'system');
13	
14	  useEffect(() => {
15	    const root = document.documentElement;
16	    const applyTheme = (dark: boolean) => {
17	      root.classList.toggle('dark', dark);
18	    };
19	
20	    if (theme === 'system') {
21	      const mql = window.matchMedia('(prefers-color-scheme: dark)');
22	      applyTheme(mql.matches);
23	      const handler = (e: MediaQueryListEvent) => applyTheme(e.matches);
24	      mql.addEventListener('change', handler);
25	      return () => mql.removeEventListener('change', handler);
26	    } else {
27	      applyTheme(theme === 'dark');
28	    }
29	  }, [theme]);
30	
31	  const contextValue = useMemo(() => ({ theme, setTheme }), [theme, setTheme]);
32	
33	  return <ThemeContext.Provider value={contextValue}>{children}</ThemeContext.Provider>;
34	}
35	
